import React from 'react';
import styles from './Advantages.module.scss';

const Advantages = () => {
  return (
    <section className={styles.advantages}>
      <h2>Наши преимущества</h2>
      <img src="/img/Advantages.png" alt="Advantages" />
      <div className={styles.advantageList}>
        <div className={styles.advantageItem}>Продакшн артистов любого уровня</div>
        <div className={styles.advantageItem}>Наши работы на радио и в популярных плейлистах</div>
        <div className={styles.advantageItem}>Топовое оборудование и лицензионный софт</div>
        <div className={styles.advantageItem}>Работа в любых жанрах</div>
      </div>
    </section>
  );
};

export default Advantages;
